update student
name=#{name}, no=#{no}, gender=#{gender}, phone=#{phone}, degree=#{degree}, violation_count=#{violationCount}, violation_score=#{violationScore}, clazz_id=#{clazzId}, id_card=#{idCard}, is_college=#{isCollege},
address=#{address}, graduation_date=#{graduationDate}
